    for r in range(h):
        for c in range(w):
            if g[r][c]!=4 and r!=2:
                o[r][c]=0
    for r,c in pts:
        for dr in (-1,0,1):
            for dc in (-1,0,1):
                if abs(dr)==abs(dc) and (dr or dc):
                    rr,cc=r+dr,c+dc
                    if 0<=rr<h and 0<=cc<w: o[rr][cc]=4
                elif dr==0 and cc>=0 and cc<=7:
