# Rule: each 4 -> shifted copy (rr+1,c) + diagonal arms UL & UR from the SHIFTED copy, growing until grid edge (stop at OOB), separator blocks nothing here except... p1 DL/DR would hit sep row - but arms are only UL/UR. Check all demos.
def f(g):
    h,w=len(g),len(g[0])
    out=[[0]*w for _ in range(h)]
    si=[(i,j) for i,row in enumerate(g) for j,v in enumerate(row) if v==4]
    sep=set(i for i,row in enumerate(g) if any(v==2 for v in row))
    for rr,cc in si:
        cr,ccc=rr+1,cc
        out[cr][ccc]=4
        for dr,dc in [(-1,-1),(-1,1)]:
            r,c=cr+dr,ccc+dc
            while r>=0 and 0<=c<w:
                if out[r][c]==0:
                    out[r][c]=4
                r+=dr; c+=dc
    return out
